def trace_call(fn):
    def wrapper(x):
        print("Before", fn.__name__)
        res = fn(x)
        return res
    return wrapper

@trace_call
def square(n):
    return n * n

def countdown(n):
    while n > 0:
        yield n
        n -= 1

print("Squared:", square(4))
print("Ticks:", list(countdown(3)))

